import {execFileSync} from 'node:child_process';
import {github,eventBatch} from './lib/github.mjs';
const token=[REDACTED],['auth','token'],{encoding:'utf8'}).trim();
const {data:r}=await github(token,'/repos/vxu-labs/dip');
const {data:t}=await github(token,`/repos/vxu-labs/dip/git/trees/${r.default_branch}?recursive=1`);
const files=t.tree.filter(x=>x.type==='blob'&&/^\.dip\/events\/task_[^/]+\/[^/]+\.json$/.test(x.path)).slice(0,32).map(x=>({...x,path:x.path.slice(5)}));
const result=await eventBatch(token,'vxu-labs/dip',files);
console.log(JSON.stringify({files:files.length,read:result.filter(x=>x.event).length,errors:result.filter(x=>x.error).map(x=>x.error)}));
